#!/usr/bin/env python3
"""Regenerate the static website after editing content/team.json. No packages required."""
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
OUT = ROOT / 'site'
DATA = json.loads((ROOT / 'content/team.json').read_text(encoding='utf-8'))
PAGES = [('home', 'Home', ''),('roster','Roster','roster/'),('matches','Matches','matches/'),('media','Media','media/'),('news','News','news/'),('about','About','about/'),('contact','Contact','contact/')]

def h(v): return html.escape(str(v),quote=True)
def img(base,name): return f'{base}assets/images/{name}'
def url(base,slug): return f'{base}{slug}' if slug else base
def logo(base,cls='brand-mark'):
 return f'<img class="{cls}" src="{img(base,"epic-elites-mark.webp")}" alt="Epic Elites emblem" width="54" height="44">'
def arrow(): return '<svg width="17" height="17" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M4 12H20M13 5L20 12L13 19" stroke="currentColor" stroke-width="1.7"/></svg>'
def mark(): return '<span class="crosshair" aria-hidden="true"><i></i><i></i><i></i><i></i></span>'
def header(active,base):
 links=''.join(f'<a href="{url(base,s)}" class="nav-link {"is-active" if k==active else ""}" {"aria-current=\"page\"" if k==active else ""}>{label}</a>' for k,label,s in PAGES)
 return f'''<a class="skip-link" href="#main">Skip to content</a><header class="site-header" id="site-header"><div class="site-header-inner"><a class="brand" href="{base}" aria-label="Epic Elites home">{logo(base)}<span class="brand-words"><strong>EPIC ELITES</strong><small>FREE FIRE ESPORTS</small></span></a><nav class="desktop-nav" aria-label="Main navigation">{links}</nav><div class="header-end"><span class="header-presence"><span class="presence-dot"></span> TEAM HQ</span><button class="menu-toggle" type="button" aria-label="Open navigation" aria-expanded="false" aria-controls="mobile-navigation"><span></span><span></span></button></div></div><nav class="mobile-nav" id="mobile-navigation" aria-label="Mobile navigation" inert><div class="mobile-nav-top"><span>EXPLORE EPIC ELITES</span><span>EST. / FF</span></div>{links}<div class="mobile-nav-foot">RISE ABOVE <span>© EPIC ELITES</span></div></nav></header>'''
def footer(base):
 social=''.join(f'<a href="{h(link)}" target="_blank" rel="noopener noreferrer">{k.capitalize()} {arrow()}</a>' for k,link in DATA['socials'].items() if link)
 social=social or '<span class="subtle">Official social links will be added here.</span>'
 nav=''.join(f'<a href="{url(base,slug)}">{label}</a>' for k,label,slug in PAGES if k!='home')
 return f'''<footer class="site-footer"><div class="container"><div class="footer-top"><div class="footer-identity">{logo(base,'footer-mark')}<p>EPIC ELITES</p><span>FREE FIRE ESPORTS TEAM</span></div><div class="footer-links"><span class="eyebrow">EXPLORE</span>{nav}</div><div class="footer-links"><span class="eyebrow">FOLLOW THE TEAM</span>{social}</div><div class="footer-message"><span class="eyebrow">THE STANDARD</span><strong>RISE<br>ABOVE<span>.</span></strong></div></div><div class="footer-bottom"><span>© <span data-year>2026</span> EPIC ELITES. ALL RIGHTS RESERVED.</span><span>BUILT FOR THE GAME. MADE FOR THE TEAM.</span><button class="back-top" type="button">BACK TO TOP ↑</button></div></div></footer>'''
def section_kicker(num,txt): return f'<span class="section-index"><b>{num}</b><span class="index-line"></span>{txt}</span>'
def card(p,i,base):
 return f'''<button class="player-card" type="button" data-player="{i}" aria-label="View {h(p['name'])} profile"><span class="player-card-top"><span>EE / {h(p['number'])}</span><span class="card-plus">+</span></span><span class="player-card-art"><span class="card-ring"></span><img src="{img(base,p['image'])}" loading="lazy" alt="Epic Elites roster portrait {h(p['number'])}"></span><span class="player-card-info"><span><small>ACTIVE ROSTER</small><strong>{h(p['name'])}</strong><em>{h(p['role'])}</em></span>{arrow()}</span></button>'''
def page_head(key,title,desc,base):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#0a090e"><meta name="description" content="{h(desc)}"><meta name="robots" content="index, follow"><meta property="og:type" content="website"><meta property="og:site_name" content="Epic Elites"><meta property="og:title" content="{h(title)}"><meta property="og:description" content="{h(desc)}"><title>{h(title)}</title><link rel="icon" href="{img(base,'epic-elites-mark.webp')}" type="image/webp"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=Rajdhani:wght@400;500;600;700&family=Space+Mono:wght@400;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="{base}assets/css/styles.css"><script>window.EE_DATA={json.dumps(DATA,ensure_ascii=False).replace('</','<\\/')}</script><script defer src="{base}assets/js/main.js"></script></head><body data-page="{key}" data-root="{base}">'''
def page_tail(base): return f'{footer(base)}<div class="toast" role="status" aria-live="polite"></div></body></html>'

def home(base):
 p=DATA['players'][2]
 thumbs=''.join(f'<button class="roster-thumb {"is-current" if i==2 else ""}" type="button" data-feature-player="{i}" aria-label="Show roster player {h(item["number"])}" aria-pressed="{str(i==2).lower()}"><img src="{img(base,item["image"])}" alt=""><span>{h(item["number"])}</span></button>' for i,item in enumerate(DATA['players']))
 return f'''<main id="main"><section class="hero" aria-labelledby="hero-title"><div class="hero-grid" aria-hidden="true"></div><div class="hero-corner-a" aria-hidden="true">01 / EE • FF</div><div class="hero-edge" aria-hidden="true">COMPETITIVE DIVISION / FREE FIRE</div><div class="hero-graphic" aria-hidden="true"><div class="rotor rotor-one"></div><div class="rotor rotor-two"></div><div class="rotor rotor-three"></div><div class="target-center"></div><div class="radar-sweep"></div></div><div class="hero-figure" data-parallax><div class="hero-figure-cut"><img src="{img(base,'player-03.webp')}" alt="Epic Elites team player wearing the official black and purple jersey" fetchpriority="high"></div></div><div class="hero-main container"><div class="hero-copy"><div class="overline"><span class="redline"></span> THE OFFICIAL TEAM WEBSITE <span class="overline-code">[ 00 / 06 ]</span></div><h1 class="hero-title" id="hero-title"><span>EPIC</span><span class="outline-title">ELITES<span class="solid-period">.</span></span></h1><p class="hero-desc">A Free Fire esports team. One identity, one roster, one mission: to rise above every challenge.</p><div class="hero-actions"><a class="button-primary magnetic" href="{url(base,'roster/')}"><span>EXPLORE THE ROSTER</span>{arrow()}</a><a class="text-link" href="{url(base,'about/')}">THE TEAM <span>↗</span></a></div></div></div><div class="hero-bottom container"><div class="hero-bottom-left">{mark()}<span>EPIC ELITES / RISE ABOVE</span></div><div class="hero-bottom-right"><span>01</span><span class="hero-progress"><i></i></span><span>05</span></div></div><canvas id="field-canvas" aria-hidden="true"></canvas></section>
 <div class="marquee-band" aria-label="Epic Elites, Rise Above"><div class="marquee-track" aria-hidden="true">{(' <span>EPIC ELITES</span><i>✳</i><span>RISE ABOVE</span><i>✳</i><span>FREE FIRE ESPORTS</span><i>✳</i>')*4}</div></div>
 <section class="section manifesto-section"><div class="container manifesto-grid"><div>{section_kicker('01','THE TEAM DNA')}<h2 class="display-heading">MORE THAN<br><span class="outlined">A NAME.</span></h2></div><div class="manifesto-right"><div class="manifesto-big-mark">{logo(base,'manifesto-logo')}<span class="mark-orbit"></span></div><p>Epic Elites is built around a shared competitive identity. The focus is simple: teamwork, commitment, and showing up prepared for every match.</p><a class="underlined-link" href="{url(base,'about/')}">LEARN ABOUT THE TEAM {arrow()}</a></div></div></section>
 <section class="section featured-roster" id="featured-roster"><div class="container"><div class="section-heading-row"><div>{section_kicker('02','THE PEOPLE')}<h2 class="display-heading">MEET THE<br><span class="purple-text">ROSTER.</span></h2></div><a class="outline-button" href="{url(base,'roster/')}">FULL ROSTER {arrow()}</a></div><div class="featured-layout"><div class="featured-selector"><span class="tiny-label">SELECT A PLAYER / 06</span><div class="roster-thumbs">{thumbs}</div><div class="selector-instructions">SELECT A PORTRAIT TO EXPLORE THE LINEUP</div></div><div class="featured-portrait"><span class="featured-number" id="featured-num">03</span><div class="featured-circle"></div><img id="featured-img" src="{img(base,p['image'])}" alt="Epic Elites roster player 03" loading="lazy"><span class="featured-corner">EE / PLAYER INDEX</span></div><div class="featured-details"><span class="tiny-label">ACTIVE ROSTER / {len(DATA['players']):02d} PLAYERS</span><div><span class="featured-position" id="featured-position">03 / 06</span><h3 id="featured-name">{h(p['name'])}</h3><p id="featured-role">{h(p['role'])}</p><div class="feature-line"></div><a href="{url(base,'roster/')}" class="underlined-link">VIEW PLAYER PROFILES {arrow()}</a></div></div></div></div></section>
 <section class="section kit-section"><div class="container kit-layout"><div class="kit-copy">{section_kicker('03','TEAM IDENTITY')}<span class="kit-mini">BLACK. PURPLE. UNMISTAKABLE.</span><h2 class="display-heading">WEAR THE<br><span class="outlined">IDENTITY.</span></h2><p>Our team colors and jersey bring the Epic Elites identity into every match.</p><a class="button-primary magnetic" href="{url(base,'media/')}">EXPLORE THE JERSEY {arrow()}</a></div><div class="kit-art"><div class="kit-art-caption">OFFICIAL TEAM KIT / FRONT & BACK</div><img src="{img(base,'team-kit.webp')}" alt="Epic Elites black and purple esports jersey, front and back view" loading="lazy"><span class="kit-diagonal"></span></div></div></section>
 <section class="section match-home"><div class="container"><div class="section-heading-row"><div>{section_kicker('04','COMPETITION')}<h2 class="display-heading">MATCH<br><span class="purple-text">CENTER.</span></h2></div><a class="outline-button" href="{url(base,'matches/')}">ALL MATCHES {arrow()}</a></div><div class="next-match"><div class="match-info-tag"><span class="live-square"></span> MATCH UPDATES</div><div class="next-match-visual"><span class="nm-label">NEXT FIXTURE</span><strong>TO BE<br>ANNOUNCED<span>.</span></strong><p>Future fixtures and verified results will appear here as soon as they are confirmed.</p></div><div class="next-match-sigil">{logo(base,'nm-logo')}<span>EE</span></div><div class="next-match-bottom"><span>FREE FIRE ESPORTS</span><a href="{url(base,'matches/')}">CHECK MATCH CENTER {arrow()}</a></div></div></div></section>
 <section class="closing-section"><div class="closing-top container">{section_kicker('05','WHAT DRIVES US')}<span>THE EPIC ELITES MINDSET</span></div><div class="closing-word" aria-label="Rise Above"><span>RISE</span><span>ABOVE<span class="purple-text">.</span></span></div><div class="closing-bottom container"><p>THE STANDARD IS SET BY THE WORK.</p><a class="outline-button" href="{url(base,'contact/')}">GET IN TOUCH {arrow()}</a></div></section></main>'''

def subhero(code,label,title,subtitle,variant=''):
 return f'''<section class="subhero {variant}"><div class="container"><div class="subhero-top">{section_kicker(code,label)}<span>EPIC ELITES / FREE FIRE</span></div><h1 class="subhero-title">{title}</h1><p class="subhero-description">{subtitle}</p><div class="subhero-index">{code} / EPIC ELITES</div></div><div class="subhero-lines" aria-hidden="true"></div></section>'''

def roster(base):
 cards=''.join(card(p,i,base) for i,p in enumerate(DATA['players']))
 return f'''<main id="main">{subhero('01','THE LINEUP','OUR <span>ROSTER.</span>','The people wearing the Epic Elites jersey. Player names and roles can be updated as the lineup is finalized.','roster-hero')}<section class="section roster-section"><div class="container"><div class="roster-toolbar"><div><span class="tiny-label">TEAM / FREE FIRE DIVISION</span><h2>ACTIVE LINEUP <sup>{len(DATA['players']):02d}</sup></h2></div><span class="roster-toolbar-right">EPIC ELITES / RISE ABOVE</span></div><div class="player-grid">{cards}</div><div class="roster-footnote"><span class="small-cross">+</span><p>Roster names, positions and player information are currently placeholders and can be edited in <code>content/team.json</code>.</p></div></div></section></main><div class="profile-overlay" id="profile-overlay" role="dialog" aria-modal="true" aria-label="Player profile" aria-hidden="true"><div class="profile-backdrop" data-close-profile></div><div class="profile-panel" tabindex="-1"><button class="profile-close" type="button" data-close-profile aria-label="Close player profile">CLOSE <span>×</span></button><div class="profile-image"><span class="profile-watermark">EE</span><img id="profile-image" src="{img(base,'player-01.webp')}" alt=""></div><div class="profile-details"><span class="tiny-label">EPIC ELITES / PLAYER PROFILE</span><span class="profile-index" id="profile-number">01 / 06</span><h2 id="profile-name">PLAYER 01</h2><span class="profile-rule"></span><dl><div><dt>TEAM</dt><dd>EPIC ELITES</dd></div><div><dt>GAME</dt><dd>FREE FIRE</dd></div><div><dt>ROLE</dt><dd id="profile-role">TO BE CONFIRMED</dd></div></dl><p id="profile-bio"></p><div class="profile-controls"><button type="button" id="profile-prev">← PREVIOUS</button><button type="button" id="profile-next">NEXT PLAYER →</button></div></div></div></div>'''

def fixture(item,kind):
 opponent=h(item.get('opponent','Opponent to be announced')); event=h(item.get('event','Tournament')); date=h(item.get('date','TBA')); label=h(item.get('result','')) if kind=='results' else h(item.get('time','TBA'))
 return f'<article class="fixture"><div class="fixture-date">{date}</div><div class="fixture-team"><span class="fixture-ee">EE</span><strong>EPIC ELITES</strong><i>VS</i><strong>{opponent}</strong></div><div class="fixture-event"><span>{event}</span><b>{label}</b></div></article>'
def matches(base):
 future=''.join(fixture(p,'upcoming') for p in DATA['upcomingMatches']) if DATA['upcomingMatches'] else '<div class="empty-match"><div class="empty-target"><span></span><span></span></div><span class="tiny-label">NO FIXTURES PUBLISHED</span><h3>THE NEXT DROP<br>IS COMING.</h3><p>There are no confirmed upcoming matches to display yet. Return here for official fixture announcements.</p></div>'
 results=''.join(fixture(p,'results') for p in DATA['results']) if DATA['results'] else '<div class="empty-match"><div class="empty-target"><span></span><span></span></div><span class="tiny-label">NO RESULTS PUBLISHED</span><h3>THE RECORD<br>STARTS HERE.</h3><p>Verified match results will appear here after they have been published by the team.</p></div>'
 return f'''<main id="main">{subhero('02','COMPETITIVE PLAY','MATCH <span>CENTER.</span>','Fixtures, tournament appearances and published results in one place.','matches-hero')}<section class="section matches-section"><div class="container"><div class="matches-heading"><div><span class="tiny-label">TOURNAMENT TRACKER / EE</span><h2>COMPETITION BOARD</h2></div><span class="tiny-label">ALL TIMES WILL BE SHOWN WHEN CONFIRMED</span></div><div class="match-tabs" role="tablist" aria-label="Matches"><button type="button" class="match-tab is-selected" id="tab-upcoming" role="tab" aria-selected="true" aria-controls="panel-upcoming" data-match-tab="upcoming">UPCOMING <span>{len(DATA['upcomingMatches']):02d}</span></button><button type="button" class="match-tab" id="tab-results" role="tab" aria-selected="false" aria-controls="panel-results" data-match-tab="results">RESULTS <span>{len(DATA['results']):02d}</span></button></div><div id="panel-upcoming" class="match-panel" role="tabpanel" aria-labelledby="tab-upcoming">{future}</div><div id="panel-results" class="match-panel" role="tabpanel" aria-labelledby="tab-results" hidden>{results}</div><div class="matches-note">MATCHES ARE ADDED ONLY WHEN INFORMATION IS CONFIRMED. NO PLACEHOLDER FIXTURES ARE DISPLAYED.</div></div></section></main>'''

def media(base):
 gallery=''.join(f'<button class="gallery-tile" type="button" data-lightbox="{img(base,p["image"])}" data-lightbox-caption="EPIC ELITES / PLAYER {h(p["number"])}" aria-label="View player {h(p["number"])} image"><img src="{img(base,p["image"])}" alt="Epic Elites roster portrait {h(p["number"])}" loading="lazy"><span>ROSTER IMAGE / {h(p["number"])}</span><i>↗</i></button>' for p in DATA['players'])
 return f'''<main id="main">{subhero('03','VISUAL IDENTITY','TEAM <span>MEDIA.</span>','The colors, the jersey, and the people behind the Epic Elites identity.','media-hero')}<section class="section kit-gallery-section"><div class="container"><div class="section-heading-row"><div>{section_kicker('01','THE KIT')}<h2 class="display-heading">MADE TO<br><span class="purple-text">REPRESENT.</span></h2></div><span class="media-intro">BLACK / PURPLE<br>EPIC ELITES / RISE ABOVE</span></div><div class="jersey-experience"><div class="jersey-viewer"><div class="jersey-stage" id="jersey-stage"><div class="jersey-face jersey-face-front"><img src="{img(base,'jersey-front.webp')}" alt="Epic Elites jersey front"></div><div class="jersey-face jersey-face-back"><img src="{img(base,'jersey-back.webp')}" alt="Epic Elites jersey back"></div></div><span class="jersey-viewer-label">360° INSPIRED VIEW / 02 SIDES</span></div><div class="jersey-sidebar"><div><span class="tiny-label">OFFICIAL TEAM KIT</span><h3>THE EPIC<br>ELITES JERSEY.</h3><p>The team emblem, signature purple accents and Rise Above detail define this jersey.</p></div><div class="jersey-controls"><span class="tiny-label">CHOOSE A VIEW</span><div><button type="button" class="jersey-choice is-current" data-jersey-side="front" aria-pressed="true">01 / FRONT VIEW <span>↗</span></button><button type="button" class="jersey-choice" data-jersey-side="back" aria-pressed="false">02 / BACK VIEW <span>↗</span></button></div></div><span class="jersey-asset-note">VIEW PREPARED FROM THE SUPPLIED JERSEY ARTWORK.</span></div></div></div></section><section class="section gallery-section"><div class="container">{section_kicker('02','THE GALLERY')}<div class="section-heading-row"><h2 class="display-heading">BEHIND<br><span class="outlined">THE TEAM.</span></h2><span class="media-intro">SELECT AN IMAGE TO VIEW IT LARGER.</span></div><div class="gallery-grid">{gallery}</div></div></section></main><div class="lightbox" id="lightbox" role="dialog" aria-modal="true" aria-label="Image viewer" aria-hidden="true"><button type="button" id="lightbox-close" aria-label="Close image viewer">CLOSE <span>×</span></button><img id="lightbox-img" src="{img(base,'player-01.webp')}" alt=""><span id="lightbox-caption">EPIC ELITES</span></div>'''

def about(base):
 return f'''<main id="main">{subhero('04','THE STORY','ABOUT <span>US.</span>','A team identity built for Free Fire competition, shaped by the people who represent it.','about-hero')}<section class="section about-intro-section"><div class="container about-intro-grid"><div>{section_kicker('01','WHO WE ARE')}<h2 class="display-heading">ONE TEAM.<br><span class="purple-text">ONE NAME.</span></h2></div><div class="about-copy"><p class="about-lead">Epic Elites is a Free Fire esports team united by competition and a shared identity.</p><p>This site is the home for our roster, matches, team media, and official updates. As the team evolves, it will document the players and moments that shape Epic Elites.</p><a href="{url(base,'roster/')}" class="underlined-link">MEET THE PLAYERS {arrow()}</a></div></div></section><section class="about-banner"><div class="container"><span>THE EPIC ELITES IDENTITY</span><div class="about-banner-mark">{logo(base,'about-logo')}</div><h2>RISE<br>ABOVE<span>.</span></h2><p>THE WORDS ON THE JERSEY. THE MINDSET BEHIND THE NAME.</p></div></section><section class="section principles-section"><div class="container">{section_kicker('02','OUR APPROACH')}<h2 class="display-heading">THE THINGS<br><span class="outlined">THAT MATTER.</span></h2><div class="principles"><article><span>01 /</span><h3>TEAMWORK</h3><p>Trust in the lineup and clarity in the way we play together.</p></article><article><span>02 /</span><h3>DISCIPLINE</h3><p>Preparation, practice, and a commitment to improving every day.</p></article><article><span>03 /</span><h3>AMBITION</h3><p>The drive to keep learning, competing, and raising our standard.</p></article></div></div></section><section class="about-end"><div class="container about-end-grid"><img src="{img(base,'team-kit.webp')}" alt="Epic Elites team jersey artwork" loading="lazy"><div>{section_kicker('03','THE IDENTITY')}<h2>BLACK.<br>PURPLE.<br><span>EPIC ELITES.</span></h2><p>A clear identity, designed to represent the team on and off the screen.</p><a href="{url(base,'media/')}" class="button-primary">SEE THE MEDIA {arrow()}</a></div></div></section></main>'''

def news(base):
 return f'''<main id="main">{subhero('05','OFFICIAL UPDATES','TEAM <span>NEWS.</span>','Announcements and updates, published when they are ready to share.','news-hero')}<section class="section news-section"><div class="container"><div class="news-lead"><div><span class="tiny-label">FEATURED / TEAM IDENTITY</span><h2>THE EPIC ELITES<br><span>VISUAL IDENTITY.</span></h2><p>Explore the team crest, signature colors and the black and purple jersey that brings the Epic Elites name together.</p><a href="{url(base,'media/')}" class="underlined-link">EXPLORE TEAM MEDIA {arrow()}</a></div><div class="news-lead-img"><img src="{img(base,'team-kit.webp')}" alt="Epic Elites jersey front and back" loading="lazy"></div></div><div class="news-subheading"><h3>LATEST ANNOUNCEMENTS</h3><span>OFFICIAL TEAM UPDATES ONLY</span></div><div class="news-empty"><span>EE / NEWSROOM</span><h4>NO NEW ANNOUNCEMENTS YET.</h4><p>Roster confirmations, match news and future updates will be published here when available.</p></div></div></section></main>'''

def contact(base):
 email=DATA.get('email','').strip()
 emailMarkup=f'<a href="mailto:{h(email)}">{h(email)} {arrow()}</a>' if email else '<span class="contact-pending">OFFICIAL EMAIL NOT YET ADDED</span>'
 social=''.join(f'<a href="{h(link)}" target="_blank" rel="noopener noreferrer">{h(k.upper())} {arrow()}</a>' for k,link in DATA['socials'].items() if link)
 social=social or '<span class="contact-pending">TEAM SOCIAL LINKS WILL APPEAR HERE</span>'
 return f'''<main id="main">{subhero('06','CONTACT THE TEAM','GET IN <span>TOUCH.</span>','Team inquiries, collaborations and other messages.','contact-hero')}<section class="section contact-section"><div class="container contact-grid"><div class="contact-left">{section_kicker('01','OPEN A CONVERSATION')}<h2 class="display-heading">LET’S<br><span class="purple-text">CONNECT.</span></h2><p>Have a message for Epic Elites? Use the form to prepare an inquiry, or reach us through an official channel when available.</p><div class="contact-detail"><span>OFFICIAL EMAIL</span>{emailMarkup}</div><div class="contact-detail"><span>SOCIAL CHANNELS</span>{social}</div></div><form class="contact-form" id="contact-form" data-email="{h(email)}"><span class="form-heading">TEAM INQUIRY <small>ALL FIELDS REQUIRED</small></span><div class="form-row"><label>YOUR NAME<input type="text" name="name" placeholder="Your full name" required maxlength="100" autocomplete="name"></label><label>EMAIL ADDRESS<input type="email" name="email" placeholder="you@example.com" required maxlength="200" autocomplete="email"></label></div><label>INQUIRY TYPE<select name="subject" required><option value="" disabled selected>Select a topic</option><option value="Partnership inquiry">Partnership inquiry</option><option value="Tournament invitation">Tournament invitation</option><option value="Media inquiry">Media inquiry</option><option value="General message">General message</option></select></label><label>YOUR MESSAGE<textarea name="message" placeholder="Tell us what you have in mind..." required minlength="10" maxlength="5000" rows="6"></textarea></label><button class="button-primary" type="submit"><span id="contact-submit-label">{('OPEN EMAIL APP' if email else 'PREPARE MESSAGE')}</span>{arrow()}</button><p class="form-note" id="contact-note">{('Your email app will open with your message ready to send.' if email else 'The team email has not been configured. You can prepare and copy your message, but this website cannot send it yet.')}</p><div class="form-feedback" id="form-feedback" role="status" aria-live="polite"></div></form></div></section></main>'''

BODY={'home':home,'roster':roster,'matches':matches,'media':media,'news':news,'about':about,'contact':contact}
META={
 'home':('Epic Elites | Free Fire Esports Team','Official home of Epic Elites, a Free Fire esports team. Meet the roster, explore the jersey and follow official match updates.'),
 'roster':('Team Roster | Epic Elites Free Fire Esports','Meet the Epic Elites Free Fire roster and explore player profiles.'),
 'matches':('Matches & Results | Epic Elites','Follow verified upcoming fixtures and published competitive results for Epic Elites Free Fire esports.'),
 'media':('Team Media & Jersey | Epic Elites','Explore the Epic Elites official black and purple esports team jersey, player portraits and gallery.'),
 'news':('Team News | Epic Elites','Read official Epic Elites team announcements, identity news and updates.'),
 'about':('About Epic Elites | Free Fire Esports','Learn about Epic Elites, our Free Fire esports identity, our roster, and the team mentality behind Rise Above.'),
 'contact':('Contact Epic Elites | Team Inquiries','Get in touch with Epic Elites for partnership, tournament, media or general team inquiries.')}

def build():
 for key,_,slug in PAGES:
  base='./' if key=='home' else '../'
  target=OUT/'index.html' if key=='home' else OUT/slug/'index.html'
  target.parent.mkdir(parents=True,exist_ok=True)
  title,desc=META[key]
  page=page_head(key,title,desc,base)+header(key,base)+BODY[key](base)+page_tail(base)
  target.write_text(page,encoding='utf-8')
  print('Built',target.relative_to(ROOT))
 (OUT/'robots.txt').write_text('User-agent: *\nAllow: /\n',encoding='utf-8')
 (OUT/'404.html').write_text(page_head('404','Page Not Found | Epic Elites','The requested page could not be found.','./')+header('none','./')+'<main id="main" class="error-404"><div class="container"><span class="tiny-label">ERROR / 404</span><h1>OUT OF<br><span>BOUNDS.</span></h1><p>That page isn’t here. Return to team headquarters.</p><a href="./" class="button-primary">BACK TO HOME →</a></div></main>'+page_tail('./'),encoding='utf-8')
 if DATA.get('siteUrl'):
  u=DATA['siteUrl'].rstrip('/')
  entries=''.join(f'<url><loc>{h(u+"/"+slug)}</loc></url>' for _,_,slug in PAGES)
  (OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+entries+'</urlset>',encoding='utf-8')
  (OUT/'robots.txt').write_text(f'User-agent: *\nAllow: /\nSitemap: {u}/sitemap.xml\n',encoding='utf-8')
 print('Done.')
if __name__=='__main__':build()
